const r = $input.item.json;
const sent = Number(r.dm_sent) || 0;
const bought = Number(r.purchased) || 0;
const cvr = sent > 0 ? ((bought / sent) * 100).toFixed(1) : '0.0';
return [{ json: {
  dm_sent: sent,
  purchased: bought,
  revenue: Number(r.revenue) || 0,
  avg_score: Number(r.avg_score).toFixed(1),
  cvr,
}}];
